WITH brand_store_profit AS ( SELECT i.i_brand, SUM(ss.ss_net_profit) AS store_profit FROM store_sales ss JOIN item i ON ss.ss_item_sk = i.i_item_sk GROUP BY i.i_brand ), brand_web_profit AS ( SELECT i.i_brand, ws.ws_web_site_sk AS site_sk, SUM(ws.ws_net_profit) AS web_profit FROM web_sales ws JOIN item i ON ws.ws_item_sk = i.i_item_sk GROUP BY i.i_brand, ws.ws_web_site_sk ) SELECT bw.i_brand, w.web_name AS web_site_name, COALESCE(bs.store_profit,0) AS store_profit, bw.web_profit, bw.web_profit + COALESCE(bs.store_profit,0) AS total_profit, DENSE_RANK() OVER (PARTITION BY bw.i_brand ORDER BY bw.web_profit + COALESCE(bs.store_profit,0) DESC) AS profit_rank FROM brand_web_profit bw LEFT JOIN brand_store_profit bs ON bw.i_brand = bs.i_brand LEFT JOIN web_site w ON bw.site_sk = w.web_site_sk ORDER BY bw.i_brand, profit_rank LIMIT 30
